push.source:
public void pushAwayFrom(Entity entity) {
    if (entity.rider != this && entity.vehicle != this) {
        if (!entity.noClip && !this.noClip) {
            double d = entity.x - this.x;
            double e = entity.z - this.z;
            double f = MathHelper.absMax(d, e);
            if (f >= 0.01F) {
                f = MathHelper.sqrt(f);
                d /= f;
                e /= f;
                double g = 1.0 / f;
                if (g > 1.0) {
                    g = 1.0;
                }

                d *= g;
                e *= g;
                d *= 0.05F;
                e *= 0.05F;
                d *= 1.0F - this.pushSpeedReduction;
                e *= 1.0F - this.pushSpeedReduction;
                if (this.rider == null) {
                    this.addVelocity(-d, 0.0, -e);
                }

                if (entity.rider == null) {
                    entity.addVelocity(d, 0.0, e);
                }
            }
        }
    }
}

rideTick.source:
public void tickRiding() {
    if (this.vehicle.removed) {
        this.vehicle = null;
    } else {
        this.velocityX = 0.0;
        this.velocityY = 0.0;
        this.velocityZ = 0.0;
        this.tick();
        if (this.vehicle != null) {
            this.vehicle.updatePassengerPosition();
            this.vehicleYaw = this.vehicleYaw + (this.vehicle.yaw - this.vehicle.prevYaw);
            this.vehiclePitch = this.vehiclePitch + (this.vehicle.pitch - this.vehicle.prevPitch);

            while (this.vehicleYaw >= 180.0) {
                this.vehicleYaw -= 360.0;
            }

            while (this.vehicleYaw < -180.0) {
                this.vehicleYaw += 360.0;
            }

            while (this.vehiclePitch >= 180.0) {
                this.vehiclePitch -= 360.0;
            }

            while (this.vehiclePitch < -180.0) {
                this.vehiclePitch += 360.0;
            }

            double d = this.vehicleYaw * 0.5;
            double e = this.vehiclePitch * 0.5;
            float f = 10.0F;
            if (d > f) {
                d = f;
            }

            if (d < -f) {
                d = -f;
            }

            if (e > f) {
                e = f;
            }

            if (e < -f) {
                e = -f;
            }

            this.vehicleYaw -= d;
            this.vehiclePitch -= e;
        }
    }
}

