    float h = lv != null ? lv.getAmplifier() + 1 : 0.0F;
    int i = MathHelper.ceil((fallDistance - 3.0F - h) * damageMultiplier);
    if (i > 0) {
        this.playSound(this.getFallSound(i), 1.0F, 1.0F);
        this.damage(DamageSource.FALL, i);
