    double d = 0.0078125;
    AbstractRailBlock.RailShapeType lv3 = state.get(lv2.getShapeProperty());
    switch (lv3) {
        case ASCENDING_EAST:
            this.velocityX -= 0.0078125;
            this.y++;
            break;
        case ASCENDING_WEST:
            this.velocityX += 0.0078125;
            this.y++;
            break;
        case ASCENDING_NORTH:
            this.velocityZ += 0.0078125;
            this.y++;
            break;
        case ASCENDING_SOUTH:
            this.velocityZ -= 0.0078125;
            this.y++;
