            this.velocityY *= 0.0;
            this.velocityZ *= 0.0;
        } else {
            this.velocityX *= 0.5;
            this.velocityY *= 0.0;
            this.velocityZ *= 0.5;
        }
    }

    double j = 0.0;
    double k = pos.getX() + 0.5 + is[0][0] * 0.5;
    double l = pos.getZ() + 0.5 + is[0][2] * 0.5;
    double m = pos.getX() + 0.5 + is[1][0] * 0.5;
    double n = pos.getZ() + 0.5 + is[1][2] * 0.5;
    e = m - k;
    f = n - l;
    if (e == 0.0) {
        this.x = pos.getX() + 0.5;
        j = this.z - pos.getZ();
    } else if (f == 0.0) {
