public void tick() {
    if (this.getDamageWobbleTicks() > 0) {
        this.setDamageWobbleTicks(this.getDamageWobbleTicks() - 1);
    }

    if (this.getDamageWobbleStrength() > 0.0F) {
        this.setDamageWobbleStrength(this.getDamageWobbleStrength() - 1.0F);
    }

    if (this.y < -64.0) {
        this.destroy();
    }

    if (!this.world.isClient && this.world instanceof ServerWorld) {
        this.world.profiler.push("portal");
        MinecraftServer minecraftServer = ((ServerWorld)this.world).getServer();
        int i = this.getMaxNetherPortalTime();
        if (this.changingDimension) {
            if (minecraftServer.isNetherAllowed()) {
                if (this.vehicle == null && this.netherPortalTime++ >= i) {
                    this.netherPortalTime = i;
                    this.netherPortalCooldown = this.getDefaultNetherPortalCooldown();
                    int j;
                    if (this.world.dimension.getType() == -1) {
                        j = 0;
                    } else {
                        j = -1;
                    }

                    this.teleportToDimension(j);
                }

                this.changingDimension = false;
            }
        } else {
            if (this.netherPortalTime > 0) {
                this.netherPortalTime -= 4;
            }

            if (this.netherPortalTime < 0) {
                this.netherPortalTime = 0;
            }
        }

        if (this.netherPortalCooldown > 0) {
            this.netherPortalCooldown--;
        }

        this.world.profiler.pop();
    }

    if (this.world.isClient) {
        if (this.clientInterpolationSteps > 0) {
            double d = this.x + (this.clientX - this.x) / this.clientInterpolationSteps;
            double e = this.y + (this.clientY - this.y) / this.clientInterpolationSteps;
            double f = this.z + (this.clientZ - this.z) / this.clientInterpolationSteps;
            double g = MathHelper.wrapDegrees(this.clientYaw - this.yaw);
            this.yaw = (float)(this.yaw + g / this.clientInterpolationSteps);
            this.pitch = (float)(this.pitch + (this.clientPitch - this.pitch) / this.clientInterpolationSteps);
            this.clientInterpolationSteps--;
            this.updatePosition(d, e, f);
            this.setRotation(this.yaw, this.pitch);
        } else {
            this.updatePosition(this.x, this.y, this.z);
            this.setRotation(this.yaw, this.pitch);
        }
    } else {
        this.prevX = this.x;
        this.prevY = this.y;
        this.prevZ = this.z;
        this.velocityY -= 0.04F;
        int k = MathHelper.floor(this.x);
        int i = MathHelper.floor(this.y);
        int j = MathHelper.floor(this.z);
        if (AbstractRailBlock.isRail(this.world, new BlockPos(k, i - 1, j))) {
            i--;
        }

        BlockPos lv = new BlockPos(k, i, j);
        BlockState lv2 = this.world.getBlockState(lv);
        if (AbstractRailBlock.isRail(lv2)) {
            this.moveOnRail(lv, lv2);
            if (lv2.getBlock() == Blocks.ACTIVATOR_RAIL) {
                this.onActivatorRail(k, i, j, lv2.get(PoweredRailBlock.POWERED));
            }
        } else {
            this.moveOffRail();
        }

        this.checkBlockCollision();
        this.pitch = 0.0F;
        double h = this.prevX - this.x;
        double l = this.prevZ - this.z;
        if (h * h + l * l > 0.001) {
            this.yaw = (float)(MathHelper.atan2(l, h) * 180.0 / Math.PI);
            if (this.yawFlipped) {
                this.yaw += 180.0F;
            }
        }

        double m = MathHelper.wrapDegrees(this.yaw - this.prevYaw);
        if (m < -170.0 || m >= 170.0) {
            this.yaw += 180.0F;
            this.yawFlipped = !this.yawFlipped;
        }

        this.setRotation(this.yaw, this.pitch);

        for (Entity lv3 : this.world.getEntitiesIn(this, this.getBoundingBox().expand(0.2F, 0.0, 0.2F))) {
            if (lv3 != this.rider && lv3.isPushable() && lv3 instanceof AbstractMinecartEntity) {
                lv3.pushAwayFrom(this);
            }
        }

        if (this.rider != null && this.rider.removed) {
            if (this.rider.vehicle == this) {
                this.rider.vehicle = null;
            }

            this.rider = null;
        }

        this.updateWaterState();
    }
}

