                this.nearbySlipperiness /= 2.0F;
            }
        }

        Vec3d lv = this.getVelocity();
        this.setVelocity(lv.x * this.velocityDecay, lv.y + d, lv.z * this.velocityDecay);
        this.yawVelocity = this.yawVelocity * this.velocityDecay;
        if (e > 0.0) {
            Vec3d lv2 = this.getVelocity();
            this.setVelocity(lv2.x, (lv2.y + e * (this.getGravity() / 0.65)) * 0.75, lv2.z);
