                    double d = i == 1 ? -lv2.z : lv2.z;
                    double e = i == 1 ? lv2.x : -lv2.x;
                    this.getWorld()
                        .playSound(
                            null, this.getX() + d, this.getY(), this.getZ() + e, lv, this.getSoundCategory(), 1.0F, 0.8F + 0.4F * this.random.nextFloat()
                        );
                }
