private void updatePaddles() {
    if (this.hasPassengers()) {
        float f = 0.0F;
        if (this.pressingLeft) {
            this.yawVelocity--;
        }

        if (this.pressingRight) {
            this.yawVelocity++;
        }

        if (this.pressingRight != this.pressingLeft && !this.pressingForward && !this.pressingBack) {
            f += 0.005F;
        }

        this.setYaw(this.getYaw() + this.yawVelocity);
        if (this.pressingForward) {
            f += 0.04F;
        }

        if (this.pressingBack) {
            f -= 0.005F;
        }

        this.setVelocity(
            this.getVelocity()
                .add(MathHelper.sin(-this.getYaw() * (float) (Math.PI / 180.0)) * f, 0.0, MathHelper.cos(this.getYaw() * (float) (Math.PI / 180.0)) * f)
        );
        this.setPaddlesMoving(
            this.pressingRight && !this.pressingLeft || this.pressingForward, this.pressingLeft && !this.pressingRight || this.pressingForward
        );
    }
}

tick.source:
public void tick() {
    this.lastLocation = this.location;
    this.location = this.checkLocation();
    if (this.location != AbstractBoatEntity.Location.UNDER_WATER && this.location != AbstractBoatEntity.Location.UNDER_FLOWING_WATER) {
        this.ticksUnderwater = 0.0F;
    } else {
        this.ticksUnderwater++;
    }

    if (!this.getWorld().isClient && this.ticksUnderwater >= 60.0F) {
        this.removeAllPassengers();
    }

    if (this.getDamageWobbleTicks() > 0) {
        this.setDamageWobbleTicks(this.getDamageWobbleTicks() - 1);
    }

    if (this.getDamageWobbleStrength() > 0.0F) {
        this.setDamageWobbleStrength(this.getDamageWobbleStrength() - 1.0F);
    }

    super.tick();
    this.updatePositionAndRotation();
    if (this.isLogicalSideForUpdatingMovement()) {
        if (!(this.getFirstPassenger() instanceof PlayerEntity)) {
            this.setPaddlesMoving(false, false);
        }

        this.updateVelocity();
        if (this.getWorld().isClient) {
            this.updatePaddles();
            this.getWorld().sendPacket(new BoatPaddleStateC2SPacket(this.isPaddleMoving(0), this.isPaddleMoving(1)));
        }

        this.move(MovementType.SELF, this.getVelocity());
    } else {
        this.setVelocity(Vec3d.ZERO);
    }

    this.tickBlockCollision();
    this.tickBlockCollision();
    this.handleBubbleColumn();

    for (int i = 0; i <= 1; i++) {
        if (this.isPaddleMoving(i)) {
            if (!this.isSilent()
                && this.paddlePhases[i] % (float) (Math.PI * 2) <= (float) (Math.PI / 4)
                && (this.paddlePhases[i] + (float) (Math.PI / 8)) % (float) (Math.PI * 2) >= (float) (Math.PI / 4)) {
                SoundEvent lv = this.getPaddleSound();
                if (lv != null) {
                    Vec3d lv2 = this.getRotationVec(1.0F);
                    double d = i == 1 ? -lv2.z : lv2.z;
                    double e = i == 1 ? lv2.x : -lv2.x;
                    this.getWorld()
                        .playSound(
                            null, this.getX() + d, this.getY(), this.getZ() + e, lv, this.getSoundCategory(), 1.0F, 0.8F + 0.4F * this.random.nextFloat()
                        );
                }
            }

            this.paddlePhases[i] = this.paddlePhases[i] + (float) (Math.PI / 8);
        } else {
            this.paddlePhases[i] = 0.0F;
        }
    }

    List<Entity> list = this.getWorld().getOtherEntities(this, this.getBoundingBox().expand(0.2F, -0.01F, 0.2F), EntityPredicates.canBePushedBy(this));
    if (!list.isEmpty()) {
        boolean bl = !this.getWorld().isClient && !(this.getControllingPassenger() instanceof PlayerEntity);

        for (Entity lv3 : list) {
            if (!lv3.hasPassenger(this)) {
                if (bl
                    && this.getPassengerList().size() < this.getMaxPassengers()
                    && !lv3.hasVehicle()
                    && this.isSmallerThanBoat(lv3)
                    && lv3 instanceof LivingEntity
                    && !(lv3 instanceof WaterCreatureEntity)
                    && !(lv3 instanceof PlayerEntity)
                    && !(lv3 instanceof CreakingEntity)) {
                    lv3.startRiding(this);
                } else {
                    this.pushAwayFrom(lv3);
                }
            }
        }
    }
}

