      this.positionReminder++;
      boolean var11 = Mth.lengthSquared(var1, var3, var5) > Mth.square(2.0E-4) || this.positionReminder >= 20;
      boolean var12 = var7 != 0.0 || var9 != 0.0;
      if (var11 && var12) {
