causeFallDamage.source:
public boolean causeFallDamage(final double fallDistance, final float damageModifier, final DamageSource damageSource) {
   double effectiveFallDistance;
   if (this.isIgnoringFallDamageFromCurrentImpulse()) {
      effectiveFallDistance = Math.min(fallDistance, this.currentImpulseImpactPos.y - this.getY());
      boolean hasLandedAboveCurrentImpulseImpactPosY = effectiveFallDistance <= 0.0;
      if (hasLandedAboveCurrentImpulseImpactPosY) {
         this.resetCurrentImpulseContext();
      } else {
         this.tryResetCurrentImpulseContext();
      }
   } else {
      effectiveFallDistance = fallDistance;
   }

   boolean damaged = super.causeFallDamage(effectiveFallDistance, damageModifier, damageSource);
   int dmg = this.calculateFallDamage(effectiveFallDistance, damageModifier);
   if (dmg > 0) {
      this.resetCurrentImpulseContext();
      this.playSound(this.getFallDamageSound(dmg), 1.0F, 1.0F);
      this.playBlockFallSound();
      this.hurt(damageSource, dmg);
      return true;
   } else {
      return damaged;
   }
}

travel.source:
public void travel(final Vec3 input) {
   if (this.isPassenger()) {
      super.travel(input);
   } else {
      if (this.isSwimming()) {
         double lookAngleY = this.getLookAngle().y;
         double multiplier = lookAngleY < -0.2 ? 0.085 : 0.06;
         if (lookAngleY <= 0.0
            || this.jumping
            || !this.level().getFluidState(BlockPos.containing(this.getX(), this.getY() + 1.0 - 0.1, this.getZ())).isEmpty()) {
            Vec3 movement = this.getDeltaMovement();
            this.setDeltaMovement(movement.add(0.0, (lookAngleY - movement.y) * multiplier, 0.0));
         }
      }

      if (this.getAbilities().flying) {
         double originalMovementY = this.getDeltaMovement().y;
         super.travel(input);
         this.setDeltaMovement(this.getDeltaMovement().with(Axis.Y, originalMovementY * 0.6));
      } else {
         super.travel(input);
      }
   }
}

aiStep.source:
public void aiStep() {
   if (this.jumpTriggerTime > 0) {
      this.jumpTriggerTime--;
   }

   this.tickRegeneration();
   this.inventory.tick();
   if (this.abilities.flying && !this.isPassenger()) {
      this.resetFallDistance();
   }

   super.aiStep();
   this.updateSwingTime();
   this.yHeadRot = this.getYRot();
   this.setSpeed((float)this.getAttributeValue(Attributes.MOVEMENT_SPEED));
   if (this.getHealth() > 0.0F && !this.isSpectator()) {
      AABB pickupArea;
      if (this.isPassenger() && !this.getVehicle().isRemoved()) {
         pickupArea = this.getBoundingBox().minmax(this.getVehicle().getBoundingBox()).inflate(1.0, 0.0, 1.0);
      } else {
         pickupArea = this.getBoundingBox().inflate(1.0, 0.5, 1.0);
      }

      List<Entity> entities = this.level().getEntities(this, pickupArea);
      List<Entity> orbs = Lists.newArrayList();

      for (Entity entity : entities) {
         if (entity.is(EntityType.EXPERIENCE_ORB)) {
            orbs.add(entity);
         } else if (!entity.isRemoved()) {
            this.touch(entity);
         }
      }

      if (!orbs.isEmpty()) {
         this.touch(Util.getRandom(orbs, this.random));
      }
   }

   this.handleShoulderEntities();
}

