   }
}

aiStep.source:
public void aiStep() {
   if (this.sprintTriggerTime > 0) {
      this.sprintTriggerTime--;
   }

   if (!(this.minecraft.gui.screen() instanceof LevelLoadingScreen)) {
      this.handlePortalTransitionEffect(this.getActivePortalLocalTransition() == Transition.CONFUSION);
      this.processPortalCooldown();
   }

   boolean wasJumping = this.input.keyPresses.jump();
   boolean wasShiftKeyDown = this.input.keyPresses.shift();
   boolean hasForwardImpulse = this.input.hasForwardImpulse();
   Abilities abilities = this.getAbilities();
   this.crouching = !abilities.flying
      && !this.isSwimming()
      && !this.isPassenger()
      && this.canPlayerFitWithinBlocksAndEntitiesWhen(Pose.CROUCHING)
      && (this.isShiftKeyDown() || !this.isSleeping() && !this.canPlayerFitWithinBlocksAndEntitiesWhen(Pose.STANDING));
   this.input.tick();
   this.minecraft.getTutorial().onInput(this.input);
   boolean wasAutoJump = false;
   if (this.autoJumpTime > 0) {
      this.autoJumpTime--;
      wasAutoJump = true;
      this.input.makeJump();
   }

   if (!this.noPhysics) {
      this.moveTowardsClosestSpace(this.getX() - this.getBbWidth() * 0.35, this.getZ() + this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() - this.getBbWidth() * 0.35, this.getZ() - this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() + this.getBbWidth() * 0.35, this.getZ() - this.getBbWidth() * 0.35);
      this.moveTowardsClosestSpace(this.getX() + this.getBbWidth() * 0.35, this.getZ() + this.getBbWidth() * 0.35);
   }

   if (wasShiftKeyDown || this.isSlowDueToUsingItem() && !this.isPassenger() || this.input.keyPresses.backward()) {
      this.sprintTriggerTime = 0;
   }

   if (this.canStartSprinting()) {
      if (!hasForwardImpulse) {
         if (this.sprintTriggerTime > 0) {
            this.setSprinting(true);
         } else {
            this.sprintTriggerTime = this.minecraft.options.sprintWindow().get();
         }
      }

      if (this.input.keyPresses.sprint()) {
         this.setSprinting(true);
      }
   }

   if (this.isSprinting()) {
      if (this.isSwimming()) {
         if (this.shouldStopSwimSprinting()) {
            this.setSprinting(false);
         }
      } else if (this.shouldStopRunSprinting()) {
         this.setSprinting(false);
      }
   }

   boolean justToggledCreativeFlight = false;
   if (abilities.mayfly) {
      if (this.minecraft.gameMode.isSpectator()) {
         if (!abilities.flying) {
            abilities.flying = true;
            justToggledCreativeFlight = true;
            this.onUpdateAbilities();
         }
      } else if (!wasJumping && this.input.keyPresses.jump() && !wasAutoJump) {
         if (this.jumpTriggerTime == 0) {
            this.jumpTriggerTime = 7;
         } else if (!this.isSwimming() && (this.getVehicle() == null || this.jumpableVehicle() != null)) {
            abilities.flying = !abilities.flying;
            if (abilities.flying && this.onGround()) {
               this.jumpFromGround();
            }

            justToggledCreativeFlight = true;
            this.onUpdateAbilities();
            this.jumpTriggerTime = 0;
         }
      }
   }

   if (this.input.keyPresses.jump() && !justToggledCreativeFlight && !wasJumping && !this.onClimbable() && this.tryToStartFallFlying()) {
      this.connection.send(new ServerboundPlayerCommandPacket(this, Action.START_FALL_FLYING));
   }

   this.wasFallFlying = this.isFallFlying();
   if (this.isInWater() && this.input.keyPresses.shift() && this.isAffectedByFluids()) {
      this.goDownInWater();
   }

   if (this.isEyeInFluid(FluidTags.WATER)) {
      int speed = this.isSpectator() ? 10 : 1;
      this.waterVisionTime = Mth.clamp(this.waterVisionTime + speed, 0, 600);
   } else if (this.waterVisionTime > 0) {
      this.isEyeInFluid(FluidTags.WATER);
      this.waterVisionTime = Mth.clamp(this.waterVisionTime - 10, 0, 600);
   }

   if (abilities.flying && this.isControlledCamera()) {
      int inputYa = 0;
      if (this.input.keyPresses.shift()) {
         inputYa--;
      }

      if (this.input.keyPresses.jump()) {
         inputYa++;
      }

      if (inputYa != 0) {
         this.setDeltaMovement(this.getDeltaMovement().add(0.0, inputYa * abilities.getFlyingSpeed() * 3.0F, 0.0));
      }
   }

   PlayerRideableJumping jumpableVehicle = this.jumpableVehicle();
   if (jumpableVehicle != null && jumpableVehicle.getJumpCooldown() == 0) {
      if (this.jumpRidingTicks < 0) {
         this.jumpRidingTicks++;
         if (this.jumpRidingTicks == 0) {
            this.jumpRidingScale = 0.0F;
         }
      }

      if (wasJumping && !this.input.keyPresses.jump()) {
         this.jumpRidingTicks = -10;
         jumpableVehicle.onPlayerJump(Mth.floor(this.getJumpRidingScale() * 100.0F));
         this.sendRidingJump();
      } else if (!wasJumping && this.input.keyPresses.jump()) {
         this.jumpRidingTicks = 0;
         this.jumpRidingScale = 0.0F;
      } else if (wasJumping) {
         this.jumpRidingTicks++;
         if (this.jumpRidingTicks < 10) {
            this.jumpRidingScale = this.jumpRidingTicks * 0.1F;
         } else {
            this.jumpRidingScale = 0.8F + 2.0F / (this.jumpRidingTicks - 9) * 0.1F;
         }
      }
   } else {
      this.jumpRidingScale = 0.0F;
   }

   super.aiStep();
   if (this.onGround() && abilities.flying && !this.minecraft.gameMode.isSpectator()) {
      abilities.flying = false;
      this.onUpdateAbilities();
   }
}

sendPosition.source:
private void sendPosition() {
   this.sendIsSprintingIfNeeded();
   if (this.isControlledCamera()) {
      double deltaX = this.getX() - this.xLast;
      double deltaY = this.getY() - this.yLast;
      double deltaZ = this.getZ() - this.zLast;
      double deltaYRot = this.getYRot() - this.yRotLast;
      double deltaXRot = this.getXRot() - this.xRotLast;
      this.positionReminder++;
      boolean move = Mth.lengthSquared(deltaX, deltaY, deltaZ) > Mth.square(2.0E-4) || this.positionReminder >= 20;
      boolean rot = deltaYRot != 0.0 || deltaXRot != 0.0;
      if (move && rot) {
         this.connection.send(new PosRot(this.position(), this.getYRot(), this.getXRot(), this.onGround(), this.horizontalCollision));
      } else if (move) {
         this.connection.send(new Pos(this.position(), this.onGround(), this.horizontalCollision));
      } else if (rot) {
         this.connection.send(new Rot(this.getYRot(), this.getXRot(), this.onGround(), this.horizontalCollision));
      } else if (this.lastOnGround != this.onGround() || this.lastHorizontalCollision != this.horizontalCollision) {
         this.connection.send(new StatusOnly(this.onGround(), this.horizontalCollision));
      }

      if (move) {
         this.xLast = this.getX();
         this.yLast = this.getY();
         this.zLast = this.getZ();
         this.positionReminder = 0;
      }

      if (rot) {
         this.yRotLast = this.getYRot();
         this.xRotLast = this.getXRot();
      }

      this.lastOnGround = this.onGround();
      this.lastHorizontalCollision = this.horizontalCollision;
      this.autoJumpEnabled = this.minecraft.options.autoJump().get();
   }
}

floatBoat.source:
private void floatBoat() {
   double vspeed = -this.getGravity();
   double buoyancy = 0.0;
   float invFriction = 0.05F;
   if (this.oldStatus == AbstractBoat.Status.IN_AIR && this.status != AbstractBoat.Status.IN_AIR && this.status != AbstractBoat.Status.ON_LAND) {
      this.waterLevel = this.getY(1.0);
      double targetY = (double)(this.getWaterLevelAbove() - this.getBbHeight()) + 0.101;
      if (this.level().noCollision(this, this.getBoundingBox().move(0.0, targetY - this.getY(), 0.0))) {
         this.setPos(this.getX(), targetY, this.getZ());
         this.setDeltaMovement(this.getDeltaMovement().multiply(1.0, 0.0, 1.0));
         this.lastYd = 0.0;
      }

      this.status = AbstractBoat.Status.IN_WATER;
   } else {
      if (this.status == AbstractBoat.Status.IN_WATER) {
         buoyancy = (this.waterLevel - this.getY()) / (double)this.getBbHeight();
         invFriction = 0.9F;
      } else if (this.status == AbstractBoat.Status.UNDER_FLOWING_WATER) {
         vspeed = -7.0E-4;
         invFriction = 0.9F;
      } else if (this.status == AbstractBoat.Status.UNDER_WATER) {
         buoyancy = 0.009999999776482582;
         invFriction = 0.45F;
      } else if (this.status == AbstractBoat.Status.IN_AIR) {
         invFriction = 0.9F;
      } else if (this.status == AbstractBoat.Status.ON_LAND) {
         invFriction = this.landFriction;
         if (this.getControllingPassenger() instanceof Player) {
            this.landFriction /= 2.0F;
         }
      }

      Vec3 movement = this.getDeltaMovement();
      this.setDeltaMovement(movement.x * (double)invFriction, movement.y + vspeed, movement.z * (double)invFriction);
      this.deltaRotation *= invFriction;
      if (buoyancy > 0.0) {
         Vec3 deltaMovement = this.getDeltaMovement();
         this.setDeltaMovement(deltaMovement.x, (deltaMovement.y + buoyancy * (this.getDefaultGravity() / 0.65)) * 0.75, deltaMovement.z);
      }
   }

}

controlBoat.source:
private void controlBoat() {
   if (this.isVehicle()) {
      float acceleration = 0.0F;
      if (this.inputLeft) {
         --this.deltaRotation;
      }

      if (this.inputRight) {
         ++this.deltaRotation;
      }

      if (this.inputRight != this.inputLeft && !this.inputUp && !this.inputDown) {
         acceleration += 0.005F;
      }

      this.setYRot(this.getYRot() + this.deltaRotation);
      if (this.inputUp) {
         acceleration += 0.04F;
      }

      if (this.inputDown) {
         acceleration -= 0.005F;
      }

      this.setDeltaMovement(this.getDeltaMovement().add((double)(Mth.sin((double)(-this.getYRot() * 0.017453292F)) * acceleration), 0.0, (double)(Mth.cos((double)(this.getYRot() * 0.017453292F)) * acceleration)));
      this.setPaddleState(this.inputRight && !this.inputLeft || this.inputUp, this.inputLeft && !this.inputRight || this.inputUp);
   }
}

tick.source:
public void tick() {
   this.oldStatus = this.status;
   this.status = this.getStatus();
   if (this.status != AbstractBoat.Status.UNDER_WATER && this.status != AbstractBoat.Status.UNDER_FLOWING_WATER) {
      this.outOfControlTicks = 0.0F;
   } else {
      ++this.outOfControlTicks;
   }

   if (!this.level().isClientSide() && this.outOfControlTicks >= 60.0F) {
      this.ejectPassengers();
   }

   if (this.getHurtTime() > 0) {
      this.setHurtTime(this.getHurtTime() - 1);
   }

   if (this.getDamage() > 0.0F) {
      this.setDamage(this.getDamage() - 1.0F);
   }

   super.tick();
   this.interpolation.interpolate();
   if (this.isLocalInstanceAuthoritative()) {
      if (!(this.getFirstPassenger() instanceof Player)) {
         this.setPaddleState(false, false);
      }

      this.floatBoat();
      if (this.level().isClientSide()) {
         this.controlBoat();
         this.level().sendPacketToServer(new ServerboundPaddleBoatPacket(this.getPaddleState(0), this.getPaddleState(1)));
      }

      this.move(MoverType.SELF, this.getDeltaMovement());
   } else {
      this.setDeltaMovement(Vec3.ZERO);
   }

   this.applyEffectsFromBlocks();
   this.applyEffectsFromBlocks();
   this.tickBubbleColumn();

   for(int i = 0; i <= 1; ++i) {
      if (this.getPaddleState(i)) {
         if (!this.isSilent() && (double)(this.paddlePositions[i] % 6.2831855F) <= 0.7853981852531433 && (double)((this.paddlePositions[i] + 0.3926991F) % 6.2831855F) >= 0.7853981852531433) {
            SoundEvent sound = this.getPaddleSound();
            if (sound != null) {
               Vec3 viewVector = this.getViewVector(1.0F);
               double dx = i == 1 ? -viewVector.z : viewVector.z;
               double dz = i == 1 ? viewVector.x : -viewVector.x;
               this.level().playSound((Entity)null, this.getX() + dx, this.getY(), this.getZ() + dz, sound, this.getSoundSource(), 1.0F, 0.8F + 0.4F * this.random.nextFloat());
            }
         }

         float[] var10000 = this.paddlePositions;
         var10000[i] += 0.3926991F;
      } else {
         this.paddlePositions[i] = 0.0F;
      }
   }

   List<Entity> entities = this.level().getEntities(this, this.getBoundingBox().inflate(0.20000000298023224, -0.009999999776482582, 0.20000000298023224), EntitySelector.pushableBy(this));
   if (!entities.isEmpty()) {
      boolean addNewPassengers = !this.level().isClientSide() && !(this.getControllingPassenger() instanceof Player);

      for(Entity entity : entities) {
         if (!entity.hasPassenger(this)) {
            if (addNewPassengers && this.getPassengers().size() < this.getMaxPassengers() && !entity.isPassenger() && this.hasEnoughSpaceFor(entity) && entity instanceof LivingEntity && !entity.is(EntityTypeTags.CANNOT_BE_PUSHED_ONTO_BOATS)) {
               entity.startRiding(this);
            } else {
               this.push(entity);
            }
         }
      }
   }

}

