   this.yRotO = this.yBodyRot = this.yHeadRot = this.getYRot();
   if (this.isLocalInstanceAuthoritative()) {
      if (riddenInput.z <= 0.0) {
         this.gallopSoundCounter = 0;
      }

      if (this.onGround()) {
         if (this.playerJumpPendingScale > 0.0F && !this.isJumping()) {
